insert into public.jp_vocab_examples(vocab_id,example_no,example_type,example_jp,example_vi,cloze_jp,answer,source_type,difficulty,focus_note)
select r.vocab_id,r.example_no,r.example_type,r.example_jp,r.example_vi,r.cloze_jp,r.answer,'generated',r.difficulty,r.focus_note
from rows r
where not exists (
  select 1 from public.jp_vocab_examples e
  where e.vocab_id=r.vocab_id and e.example_type=r.example_type
);
